arguments.command:
cd /tmp/sv-b6c853cb812b4dfdb37db8c1dd560e56
# The FUNC symbols max out at ~0x2ec4f0, but our addresses are 0x2f4b20 and 0x2f4c84
# These are likely in a section past the regular code. Check what section they're in.
aarch64-linux-gnu-readelf -SW libmonosgen-2.0.so.debug 2>/dev/null | head -40

# Also try using DWARF debug_info
pip install pyelftools 2>/dev/null | tail -1
python3 -c "
import elftools.elf.elffile as ef
import sys

with open('libmonosgen-2.0.so.debug', 'rb') as f:
    elf = ef.ELFFile(f)
    if elf.has_dwarf_info():
        di = elf.get_dwarf_info()
        for cu in di.iter_CUs():
            for die in cu.iter_DIEs():
                if die.tag == 'DW_TAG_subprogram':
                    lo = die.attributes.get('DW_AT_low_pc')
                    hi = die.attributes.get('DW_AT_high_pc')
                    name = die.attributes.get('DW_AT_name')
                    if lo and name:
                        lo_val = lo.value
                        if hi:
                            hi_val = hi.value
                            if hi.form == 'DW_FORM_data4' or hi.form == 'DW_FORM_data8':
                                hi_val = lo_val + hi_val
                        else:
                            hi_val = lo_val + 1
                        for addr in [0x2f4b20, 0x2f4c84, 0x2c1a40]:
                            if lo_val <= addr < hi_val:
                                print(f'0x{addr:x} => {name.value.decode()} (base 0x{lo_val:x})')
" 2>&1 | head -20

